          "text": "SearchForm.ts ```import { useState } from 'react'; export const useSearchForm = (initialValues?: Partial&lt;SearchFormState&gt;) =&gt; { const [freeWord, setFreeWord] = useState(initialValues?.freeWord || ''); const [language, setLanguage] = useState(initialValues?.language || ''); const [minPrice, setMinPrice] = useState(initialValues?.minPrice || ''); const [maxPrice, setMaxPrice] = useState(initialValues?.maxPrice || ''); const [location, setLocation] = useState(initialValues?.location || ''); const [minAge, setMinAge] = useState(initialValues?.minAge || ''); const [maxAge, setMaxAge] = useState(initialValues?.maxAge || ''); const [startDate, setStartDate] = useState(initialValues?.startDate || ''); const [remote, setRemote] = useState(initialValues?.remote || ''); const handleClearFilter = () =&gt; { setFreeWord(''); setLanguage(''); setMinPrice(''); setMaxPrice(''); setLocation(''); setMinAge(''); setMaxAge(''); setStartDate(''); setRemote(''); }; return { freeWord, setFreeWord, language, setLanguage, minPrice, setMinPrice, maxPrice, setMaxPrice, location, setLocation, minAge, setMinAge, maxAge, setMaxAge, startDate, setStartDate, remote, setRemote, handleClearFilter, }; }; export type SearchFormState = { freeWord: string; language: string; minPrice: string; maxPrice: string; location: string; minAge: string; maxAge: string; startDate: string; remote: string; }; export const INPUT_BASE_CLASS = \"bg-gray-50 border border-gray-300 rounded text-sm h-8 box-border\";```",
          "rawText": "SearchForm.ts\n```import { useState } from 'react';\n\nexport const useSearchForm = (initialValues?: Partial&lt;SearchFormState&gt;) =&gt; {\n  const [freeWord, setFreeWord] = useState(initialValues?.freeWord || '');\n  const [language, setLanguage] = useState(initialValues?.language || '');\n  const [minPrice, setMinPrice] = useState(initialValues?.minPrice || '');\n  const [maxPrice, setMaxPrice] = useState(initialValues?.maxPrice || '');\n  const [location, setLocation] = useState(initialValues?.location || '');\n  const [minAge, setMinAge] = useState(initialValues?.minAge || '');\n  const [maxAge, setMaxAge] = useState(initialValues?.maxAge || '');\n  const [startDate, setStartDate] = useState(initialValues?.startDate || '');\n  const [remote, setRemote] = useState(initialValues?.remote || '');\n\n  const handleClearFilter = () =&gt; {\n    setFreeWord('');\n    setLanguage('');\n    setMinPrice('');\n    setMaxPrice('');\n    setLocation('');\n    setMinAge('');\n    setMaxAge('');\n    setStartDate('');\n    setRemote('');\n  };\n\n  return {\n    freeWord,\n    setFreeWord,\n    language,\n    setLanguage,\n    minPrice,\n    setMinPrice,\n    maxPrice,\n    setMaxPrice,\n    location,\n    setLocation,\n    minAge,\n    setMinAge,\n    maxAge,\n    setMaxAge,\n    startDate,\n    setStartDate,\n    remote,\n    setRemote,\n    handleClearFilter,\n  };\n};\n\nexport type SearchFormState = {\n  freeWord: string;\n  language: string;\n  minPrice: string;\n  maxPrice: string;\n  location: string;\n  minAge: string;\n  maxAge: string;\n  startDate: string;\n  remote: string;\n};\n\nexport const INPUT_BASE_CLASS = \"bg-gray-50 border border-gray-300 rounded text-sm h-8 box-border\";```",
