          "user": "U0A0QFEQGRX",
          "userName": "貴志雪乃",
          "userRealName": "貴志雪乃",
          "text": "<@U0A0QFEQGRX>さんがチャンネルに参加しました",
          "rawText": "<@U0A0QFEQGRX>さんがチャンネルに参加しました",
          "messageTs": "1764313974.368149",
          "threadTs": null,
          "parentUserId": null,
          "subtype": "channel_join",
          "date": "2025-11-28",
